import { commonEvent, changeGold, changeItems, changeWeapons, changeArmors, changePartyMember, itemRef, weaponRef, armorRef, actorRef } from "rpgmaker-event-dsl";

const input = { item: itemRef({ id: 1 }), operation: "gain", amount: { kind: "constant", value: 1 }, extra: true } as unknown as Parameters<typeof changeItems>[0];
export const inventory = commonEvent({ id: 1, name: "Inventory", trigger: "none", commands: [changeItems(input)] });
